// Application tables (ARCHITECTURE.md section 4, as amended by ADR-0001, 0003 and 0004).
// The auth library's own tables live in auth-schema.ts, which is generated; do not edit that file.
import { sql } from "drizzle-orm";
import {
  bigint,
  boolean,
  char,
  check,
  customType,
  date,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";
import { user } from "./auth-schema";

/** Case-insensitive text (the `citext` extension, created in the first migration). */
const citext = customType<{ data: string }>({ dataType: () => "citext" });
const bytea = customType<{ data: Buffer }>({ dataType: () => "bytea" });

const timestamptz = (name: string) => timestamp(name, { withTimezone: true });
const minorUnits = (name: string) => bigint(name, { mode: "number" });

/** Largest amount in minor units, kept in step with MAX_AMOUNT_MINOR in @evenly/core (ADR-0004). */
const MAX_AMOUNT_SQL = sql.raw("1000000000000");

export const memberRole = pgEnum("member_role", ["owner", "admin", "member"]);
export const splitMethod = pgEnum("split_method", ["equal", "exact", "percent", "shares"]);
export const expenseCategory = pgEnum("expense_category", [
  "food",
  "groceries",
  "transport",
  "rent",
  "utilities",
  "entertainment",
  "travel",
  "shopping",
  "other",
]);

export const groups = pgTable(
  "groups",
  {
    id: uuid("id").primaryKey(),
    name: text("name").notNull(),
    currency: char("currency", { length: 3 }).notNull(),
    emoji: text("emoji"),
    simplifyDebts: boolean("simplify_debts").notNull().default(true),
    createdBy: uuid("created_by").references(() => user.id, { onDelete: "set null" }),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
    updatedAt: timestamptz("updated_at").notNull().defaultNow(),
    archivedAt: timestamptz("archived_at"),
    deletedAt: timestamptz("deleted_at"),
  },
  (table) => [check("groups_name_length", sql`char_length(${table.name}) BETWEEN 1 AND 100`)],
);

export const groupMembers = pgTable(
  "group_members",
  {
    id: uuid("id").primaryKey(),
    groupId: uuid("group_id")
      .notNull()
      .references(() => groups.id),
    /** NULL for a placeholder member, or for a deleted user (who also has left_at set; ADR-0003). */
    userId: uuid("user_id").references(() => user.id, { onDelete: "set null" }),
    displayName: text("display_name").notNull(),
    email: citext("email"),
    role: memberRole("role").notNull().default("member"),
    /** Defines the canonical member order (with id): who receives odd minor units. */
    joinedAt: timestamptz("joined_at").notNull().defaultNow(),
    leftAt: timestamptz("left_at"),
  },
  (table) => [
    // A user has at most one membership row per group; rejoining reactivates it.
    uniqueIndex("group_members_user_uq")
      .on(table.groupId, table.userId)
      .where(sql`${table.userId} IS NOT NULL`),
    index("group_members_user_idx").on(table.userId),
  ],
);

export const groupInvites = pgTable(
  "group_invites",
  {
    id: uuid("id").primaryKey(),
    groupId: uuid("group_id")
      .notNull()
      .references(() => groups.id),
    /** sha256 of a 32-byte random token; the token itself is never stored. */
    tokenHash: bytea("token_hash").notNull().unique(),
    createdBy: uuid("created_by")
      .notNull()
      .references(() => groupMembers.id),
    email: citext("email"),
    claimMemberId: uuid("claim_member_id").references(() => groupMembers.id),
    expiresAt: timestamptz("expires_at"),
    maxUses: integer("max_uses"),
    useCount: integer("use_count").notNull().default(0),
    revokedAt: timestamptz("revoked_at"),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
  },
  (table) => [check("group_invites_max_uses", sql`${table.maxUses} > 0`)],
);

export const expenses = pgTable(
  "expenses",
  {
    /** Generated by the client, so that creating an expense is idempotent. */
    id: uuid("id").primaryKey(),
    groupId: uuid("group_id")
      .notNull()
      .references(() => groups.id),
    description: text("description").notNull(),
    amountMinor: minorUnits("amount_minor").notNull(),
    currency: char("currency", { length: 3 }).notNull(),
    category: expenseCategory("category").notNull().default("other"),
    expenseDate: date("expense_date", { mode: "string" }).notNull(),
    notes: text("notes"),
    splitMethod: splitMethod("split_method").notNull(),
    createdBy: uuid("created_by")
      .notNull()
      .references(() => groupMembers.id),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
    updatedAt: timestamptz("updated_at").notNull().defaultNow(),
    deletedAt: timestamptz("deleted_at"),
    /** Optimistic locking: an update must name the version it read. */
    version: integer("version").notNull().default(1),
  },
  (table) => [
    check("expenses_description_length", sql`char_length(${table.description}) BETWEEN 1 AND 200`),
    check("expenses_amount_range", sql`${table.amountMinor} BETWEEN 1 AND ${MAX_AMOUNT_SQL}`),
    index("expenses_group_date_idx")
      .on(table.groupId, table.expenseDate.desc(), table.id.desc())
      .where(sql`${table.deletedAt} IS NULL`),
  ],
);

export const expensePayers = pgTable(
  "expense_payers",
  {
    expenseId: uuid("expense_id")
      .notNull()
      .references(() => expenses.id, { onDelete: "cascade" }),
    memberId: uuid("member_id")
      .notNull()
      .references(() => groupMembers.id),
    amountMinor: minorUnits("amount_minor").notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.expenseId, table.memberId] }),
    check("expense_payers_amount_range", sql`${table.amountMinor} BETWEEN 1 AND ${MAX_AMOUNT_SQL}`),
  ],
);

export const expenseShares = pgTable(
  "expense_shares",
  {
    expenseId: uuid("expense_id")
      .notNull()
      .references(() => expenses.id, { onDelete: "cascade" }),
    memberId: uuid("member_id")
      .notNull()
      .references(() => groupMembers.id),
    amountMinor: minorUnits("amount_minor").notNull(),
    /** The user's input: percent, share weight or exact amount; NULL for an equal split. */
    inputValue: numeric("input_value", { precision: 20, scale: 2 }),
  },
  (table) => [
    primaryKey({ columns: [table.expenseId, table.memberId] }),
    check("expense_shares_amount_range", sql`${table.amountMinor} BETWEEN 0 AND ${MAX_AMOUNT_SQL}`),
  ],
);

export const settlements = pgTable(
  "settlements",
  {
    id: uuid("id").primaryKey(),
    groupId: uuid("group_id")
      .notNull()
      .references(() => groups.id),
    /** The member who paid. */
    fromMemberId: uuid("from_member_id")
      .notNull()
      .references(() => groupMembers.id),
    /** The member who received the money. */
    toMemberId: uuid("to_member_id")
      .notNull()
      .references(() => groupMembers.id),
    amountMinor: minorUnits("amount_minor").notNull(),
    currency: char("currency", { length: 3 }).notNull(),
    settledOn: date("settled_on", { mode: "string" }).notNull(),
    note: text("note"),
    createdBy: uuid("created_by")
      .notNull()
      .references(() => groupMembers.id),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
    updatedAt: timestamptz("updated_at").notNull().defaultNow(),
    deletedAt: timestamptz("deleted_at"),
    version: integer("version").notNull().default(1),
  },
  (table) => [
    check("settlements_distinct_members", sql`${table.fromMemberId} <> ${table.toMemberId}`),
    check("settlements_amount_range", sql`${table.amountMinor} BETWEEN 1 AND ${MAX_AMOUNT_SQL}`),
  ],
);

export const activity = pgTable(
  "activity",
  {
    id: uuid("id").primaryKey(),
    groupId: uuid("group_id")
      .notNull()
      .references(() => groups.id),
    actorId: uuid("actor_id").references(() => groupMembers.id),
    /** 'expense.created' | 'expense.updated' | 'settlement.deleted' | 'member.joined' | ... */
    kind: text("kind").notNull(),
    entityId: uuid("entity_id"),
    /** { field: [old, new] } for updates; a snapshot for deletes. */
    diff: jsonb("diff"),
    createdAt: timestamptz("created_at").notNull().defaultNow(),
  },
  (table) => [index("activity_group_idx").on(table.groupId, table.createdAt.desc())],
);

/**
 * Secrets the instance generates for itself, such as the session secret when SESSION_SECRET is not
 * set (ADR-0007).
 */
export const instanceSecrets = pgTable("instance_secrets", {
  name: text("name").primaryKey(),
  value: text("value").notNull(),
  createdAt: timestamptz("created_at").notNull().defaultNow(),
});
